window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][34]={"university_physics_de:M34-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M34-L1 – Qubits, Bloch-Kugel und projektive Messung<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Hilberträume und\nQuantenzustände; M33-L2: Zwei-Niveau-Systeme.<\/p>\n<p><strong>Lernziel:<\/strong> Einen normierten Qubit-Zustand\nparametrisieren und die beiden Messwahrscheinlichkeiten berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein klassisches Bit besitzt einen von zwei Zuständen. Ein reines\nQubit wird dagegen durch normierte komplexe Amplituden beschrieben,\nderen Betragsquadrate Wahrscheinlichkeiten ergeben. Die Bloch-Kugel\nvisualisiert nur reine Zustände auf ihrer Oberfläche; gemischte Zustände\nliegen innerhalb der Kugel. Eine globale Phase ist nicht messbar, die\nrelative Phase zwischen den Basisamplituden ist jedoch physikalisch\nwichtig.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Nach Festlegung einer globalen Phase lässt sich jeder reine\nQubit-Zustand durch Polarwinkel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\theta\\in[0,\\pi]<\/annotation><\/semantics><\/math>\nund Azimut\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\phi\\in[0,2\\pi)<\/annotation><\/semantics><\/math>\nschreiben. Bei einer Messung in der Basis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>,<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\{|0\\rangle,|1\\rangle\\}<\/annotation><\/semantics><\/math>\nliefert die Born-Regel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P(0)=\\cos^2(\\theta/2)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>θ<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P(1)=\\sin^2(\\theta/2)<\/annotation><\/semantics><\/math>.\nDer Bloch-Vektor lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>ϕ<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>ϕ<\/mi><mo>,<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf r=(\\sin\\theta\\cos\\phi,\\sin\\theta\\sin\\phi,\\cos\\theta)<\/annotation><\/semantics><\/math>.\nEine Dichtematrix\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>I<\/mi><mo>+<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝝈<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=(I+\\mathbf r\\cdot\\boldsymbol\\sigma)/2<\/annotation><\/semantics><\/math>\nerlaubt später auch Mischzustände mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi mathvariant=\"bold-italic\">𝒓<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|\\mathbf r|\\le1<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>ψ<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mfrac><mi>θ<\/mi><mn>2<\/mn><\/mfrac><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><msup><mi>e<\/mi><mrow><mi>i<\/mi><mi>ϕ<\/mi><\/mrow><\/msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mfrac><mi>θ<\/mi><mn>2<\/mn><\/mfrac><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|\\psi\\rangle=\\cos\\frac{\\theta}{2}|0\\rangle+e^{i\\phi}\\sin\\frac{\\theta}{2}|1\\rangle.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\theta=\\pi/3<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\phi=0<\/annotation><\/semantics><\/math>\nergeben sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(0)=3/4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(1)=1/4<\/annotation><\/semantics><\/math>.\nDer Bloch-Vektor bildet mit der positiven z-Achse den Winkel 60°. Die\nGrafik zeigt die gewählte xz-Schnittebene und die z-Projektion. Bei\nwiederholter Präparation und ideal identischen Messungen erwarten wir\nfür 400 Wiederholungen ungefähr 300 Mal das Ergebnis 0, aber keine exakt\nfestgelegten Häufigkeiten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_234_DE.svg\"\nalt=\"Bloch-Kugel im xz-Schnitt mit Zustandsvektor bei 60 Grad und z-Projektion.\" />\n<figcaption aria-hidden=\"true\">Bloch-Kugel im xz-Schnitt mit\nZustandsvektor bei 60 Grad und z-Projektion.<\/figcaption>\n<\/figure>\n<p><em>Reiner Qubit-Zustand und Messachse im vereinfachten\nBloch-Schnitt.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Messwahrscheinlichkeiten gelten für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\theta=\\pi/2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welcher Bloch-z-Wert folgt aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(0)=3/4<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist die Bloch-Oberfläche keine Darstellung jedes gemischten\nZustands?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(0)=P(1)=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">r_z=P(0)-P(1)=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Gemischte Zustände besitzen im Allgemeinen einen kürzeren\nBloch-Vektor innerhalb der Kugel.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Kugel ist eine Darstellung eines isolierten Zwei-Niveau-Systems;\nsie ersetzt kein Mehr-Qubit-Tensorprodukt. Messachsen und Basis müssen\nangegeben werden. Statistische Häufigkeiten schwanken auch bei perfekter\nPräparation.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Qubit-Amplituden und Phasen bilden den Ausgangspunkt für\nVerschränkung und Gatteroperationen. <a\nhref=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information\">IBM Quantum Learning – Basics of Quantum Information<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Qubit-Zustände, Messungen, Bell-Zustände und grundlegende Schaltungen; Themen und ausgewählte Formeln; Fachlicher Bezug zur Lektion: M34-L1 – Qubits, Bloch-Kugel und projektive Messung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/general-formulation-of-quantum-information/quantum-channels/quantum-channel-basics\">IBM Quantum Learning – Quantum Channel Basics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Dichtematrizen und Quantenkanäle; gewählter Mischparameter ist ausdrücklich lektionsintern definiert; Fachlicher Bezug zur Lektion: M34-L1 – Qubits, Bloch-Kugel und projektive Messung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M34-L2 – Verschränkung, Bell-Zustände und CHSH-Korrelationen<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Tensorprodukte und Spin;\nM34-L1: Qubits.<\/p>\n<p><strong>Lernziel:<\/strong> Die Grenze lokaler CHSH-Modelle von der\nquantenmechanischen Vorhersage unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein verschränkter Zustand zweier Qubits lässt sich nicht als Produkt\nzweier einzelner Zustandsvektoren schreiben. Für den Bell-Zustand |Φ⁺⟩\nsind gleichgerichtete Messresultate in der Rechenbasis perfekt\nkorreliert, obwohl jedes Qubit für sich ein zufälliges Ergebnis liefert.\nKorrelation allein beweist allerdings keine Verschränkung:\nUnterscheidbar wird sie unter geeigneten Messbedingungen durch\nBell-Tests.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für den Spin-Singulettzustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msup><mi mathvariant=\"normal\">Ψ<\/mi><mo>−<\/mo><\/msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>01<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">|\\Psi^-\\rangle=(|01\\rangle-|10\\rangle)/\\sqrt2<\/annotation><\/semantics><\/math>\nergeben Spinmessungen in einer Ebene\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">cos<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>−<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E(a,b)=-\\cos(a-b)<\/annotation><\/semantics><\/math>.\nDefiniere\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mo>,<\/mo><mi>b<\/mi><mi>′<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mi>′<\/mi><mo>,<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>a<\/mi><mi>′<\/mi><mo>,<\/mo><mi>b<\/mi><mi>′<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">S=E(a,b)+E(a,b\\prime)+E(a\\prime,b)-E(a\\prime,b\\prime)<\/annotation><\/semantics><\/math>.\nJedes lokal-realistische Modell mit geeignetem Unabhängigkeits- und\nMessannahmen erfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>≤<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|S|\\le2<\/annotation><\/semantics><\/math>;\ndie Quantenmechanik erlaubt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">2\\sqrt2<\/annotation><\/semantics><\/math>.\nDas Ergebnis bedeutet keine überlichtschnelle Signalübertragung.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>S<\/mi><msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">L<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/msub><mo>≤<\/mo><mn>2<\/mn><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>S<\/mi><msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">Q<\/mi><mi mathvariant=\"normal\">M<\/mi><\/mrow><\/msub><mo>≤<\/mo><mn>2<\/mn><msqrt><mn>2<\/mn><\/msqrt><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">|S|_{\\mathrm{LHV}}\\le2,\\qquad |S|_{\\mathrm{QM}}\\le2\\sqrt2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Wähle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a=0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mi>′<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a\\prime=\\pi/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">b=\\pi/4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mi>′<\/mi><mo>=<\/mo><mi>−<\/mi><mi>π<\/mi><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">b\\prime=-\\pi/4<\/annotation><\/semantics><\/math>.\nDann sind die vier Korrelationen in der Reihenfolge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><mo>,<\/mo><mi>+<\/mi><mn>1<\/mn><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">-1/\\sqrt2,-1/\\sqrt2,-1/\\sqrt2,+1/\\sqrt2<\/annotation><\/semantics><\/math>.\nDamit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S<\/mi><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><msqrt><mn>2<\/mn><\/msqrt><mo>≈<\/mo><mi>−<\/mi><mn>2<\/mn><mo>,<\/mo><mn>828<\/mn><\/mrow><annotation encoding=\"application/x-tex\">S=-2\\sqrt2\\approx-2{,}828<\/annotation><\/semantics><\/math>.\nDie Grafik vergleicht die absolute lokale Grenze mit dem\nquantenmechanisch erreichbaren Betrag; sie stellt keine Messdaten\ndar.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_082_DE.svg\"\nalt=\"Vergleich zweier Betragsgrenzen des CHSH-Ausdrucks: lokal zwei, Quantenmaximum etwa 2,83.\" />\n<figcaption aria-hidden=\"true\">Vergleich zweier Betragsgrenzen des\nCHSH-Ausdrucks: lokal zwei, Quantenmaximum etwa 2,83.<\/figcaption>\n<\/figure>\n<p><em>CHSH-Betragsgrenzen für lokale Modelle und ideale\nQuantenkorrelationen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Maximalzahl ist für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|S|<\/annotation><\/semantics><\/math>\nin einem lokalen CHSH-Modell erlaubt?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>S<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|S|<\/annotation><\/semantics><\/math>\nfür die gewählten Winkel?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum lässt sich durch das Singulett nicht unmittelbar ein Bit\nsenden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>2<\/mn><annotation encoding=\"application/x-tex\">2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><msqrt><mn>2<\/mn><\/msqrt><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>828<\/mn><\/mrow><annotation encoding=\"application/x-tex\">2\\sqrt2\\approx2{,}828<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die einzelnen lokalen Ergebnisse sind zufällig; die Korrelation\nzeigt sich erst nach klassischem Vergleich.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die CHSH-Grenze ist an die Voraussetzungen des Tests gebunden.\nDetektion, Zufallsauswahl und mögliche Schlupflöcher sind experimentell\nrelevant; der Satz erklärt nicht beliebige statistische\nKorrelationen.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Verschränkung ist eine nutzbare Ressource für\nQuanteninformationsprotokolle. <a\nhref=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information/multiple-systems/quantum-information\">IBM Quantum Learning – Quantum Information and Bell States<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Darstellung und Interpretation verschränkter Bell-Zustände; Fachlicher Bezug zur Lektion: M34-L2 – Verschränkung, Bell-Zustände und CHSH-Korrelationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/docs/en/tutorials/chsh-inequality\">IBM Quantum Documentation – CHSH Inequality<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · CHSH-Korrelationsmessungen und experimentelle Verletzung; Messwinkel im Text als eigenes Beispiel; Fachlicher Bezug zur Lektion: M34-L2 – Verschränkung, Bell-Zustände und CHSH-Korrelationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M34-L3 – Quantengatter, Schaltkreise und Bell-Präparation<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M34-L1: Qubit-Amplituden; M34-L2:\nBell-Zustände.<\/p>\n<p><strong>Lernziel:<\/strong> Aus |00⟩ mit H und CNOT einen Bell-Zustand\nherleiten und Messkorrelationen bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Quantenschaltkreise trennen reversible unitäre Operationen von\nMessungen. Ein Hadamard-Gatter H erzeugt aus |0⟩ eine Superposition. Ein\nkontrolliertes NOT-Gatter (CNOT) invertiert das Zielqubit genau dann,\nwenn das Kontrollqubit in der Basis |1⟩ ist. Diese zwei Operationen\nerzeugen aus einem Produktzustand einen verschränkten Zustand.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Beginne mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>00<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|00\\rangle<\/annotation><\/semantics><\/math>.\nDie Operation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>H<\/mi><mo>⊗<\/mo><mi>I<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(H\\otimes I)<\/annotation><\/semantics><\/math>\nerzeugt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>00<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">(|00\\rangle+|10\\rangle)/\\sqrt2<\/annotation><\/semantics><\/math>.\nAnschließend verschiebt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">C<\/mi><mi mathvariant=\"normal\">N<\/mi><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{CNOT}<\/annotation><\/semantics><\/math>\nden zweiten Zweig zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>11<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|11\\rangle<\/annotation><\/semantics><\/math>.\nDie Messverteilung in der Rechenbasis hat nur die Ergebnisse 00 und 11,\njeweils mit Wahrscheinlichkeit 1/2. Eine solche Korrelation allein\nunterscheidet noch nicht zwischen klassischer Mischung und kohärenter\nVerschränkung: Messungen in weiteren Basen sind erforderlich.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">C<\/mi><mi mathvariant=\"normal\">N<\/mi><mi mathvariant=\"normal\">O<\/mi><mi mathvariant=\"normal\">T<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>H<\/mi><mo>⊗<\/mo><mi>I<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>00<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>00<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>11<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><msqrt><mn>2<\/mn><\/msqrt><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{CNOT}(H\\otimes I)|00\\rangle=\\frac{|00\\rangle+|11\\rangle}{\\sqrt2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Die Grafik zeigt zwei Eingangsqubits, das Hadamard-Gatter auf der\noberen Leitung und das anschließende CNOT mit oberem Kontrollpunkt. Nach\nidealer Präparation würde eine Serie von 200 Messungen ungefähr 100\nErgebnisse 00 und 100 Ergebnisse 11 liefern. Die Ergebnisse 01 und 10\ntreten ideal nicht auf.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_231_DE.svg\"\nalt=\"Zwei Qubit-Leitungen: Hadamard auf dem ersten Qubit und CNOT vom ersten zum zweiten.\" />\n<figcaption aria-hidden=\"true\">Zwei Qubit-Leitungen: Hadamard auf dem\nersten Qubit und CNOT vom ersten zum zweiten.<\/figcaption>\n<\/figure>\n<p><em>Schaltkreis zur Präparation des verschränkten Zustands\nΦ⁺.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welcher Zustand entsteht unmittelbar nach H auf dem ersten\nQubit?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Wahrscheinlichkeit hat das Ergebnis 01 am idealen\nSchaltungsende?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Woran erkennt man die Kohärenz gegenüber einer klassischen\n00/11-Mischung?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>00<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msqrt><mn>2<\/mn><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">(|00\\rangle+|10\\rangle)/\\sqrt2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Durch korrelierte Messungen in einer weiteren, geeigneten Basis,\netwa der X-Basis.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Diagramm idealisiert fehlerfreie Qubits und Gatter. Auf realer\nHardware treten Zustandspräparations-, Gatter- und Auslesefehler auf.\nGatter können physikalisch durch verschiedene Pulse oder\nWechselwirkungen realisiert werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Schaltkreise sind die Grundlage von Quantenalgorithmen und\nFehlerdiagnose. <a href=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information/quantum-circuits/circuits\">IBM Quantum Learning – Quantum Circuits<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Hadamard/CNOT-Schaltungen zur Bell-Zustandspräparation; Fachlicher Bezug zur Lektion: M34-L3 – Quantengatter, Schaltkreise und Bell-Präparation · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/basics-of-quantum-information\">IBM Quantum Learning – Basics of Quantum Information<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Qubit-Zustände, Messungen, Bell-Zustände und grundlegende Schaltungen; Themen und ausgewählte Formeln; Fachlicher Bezug zur Lektion: M34-L3 – Quantengatter, Schaltkreise und Bell-Präparation · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M34-L4 – Grover-Suche und Quanten-Amplitudenverstärkung<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M34-L3: Quantengatter; M31:\nnumerische Simulation.<\/p>\n<p><strong>Lernziel:<\/strong> Die ideale\nGrover-Erfolgswahrscheinlichkeit für eine markierte Datenbankposition\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Bei einer unstrukturierten Suche durch N Kandidaten muss ein\nklassischer Algorithmus im ungünstigen Fall viele Kandidaten testen.\nGrovers Quantenalgorithmus verwendet eine Phasenmarkierung (Orakel) und\nSpiegelung um den Mittelwert (Diffusion), um die Amplitude gesuchter\nErgebnisse zu verstärken. Der Vorteil betrifft die Anzahl idealer\nOrakelaufrufe, nicht automatisch die gesamte Laufzeit inklusive\nDatenvorbereitung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>M<\/mi><annotation encoding=\"application/x-tex\">M<\/annotation><\/semantics><\/math>\ngleichwertig markierten Zuständen unter\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nMöglichkeiten setzt man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>θ<\/mi><mo>=<\/mo><msqrt><mrow><mi>M<\/mi><mi>/<\/mi><mi>N<\/mi><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\sin\\theta=\\sqrt{M/N}<\/annotation><\/semantics><\/math>.\nNach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>r<\/mi><annotation encoding=\"application/x-tex\">r<\/annotation><\/semantics><\/math>\nvollständigen Grover-Iterationen hat die Zielmenge die\nWahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>r<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>θ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P_r=\\sin^2((2r+1)\\theta)<\/annotation><\/semantics><\/math>.\nDie optimale ganze Iterationszahl liegt grob bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r<\/mi><mo>≈<\/mo><mfrac><mi>π<\/mi><mn>4<\/mn><\/mfrac><msqrt><mrow><mi>N<\/mi><mi>/<\/mi><mi>M<\/mi><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">r\\approx\\frac\\pi4\\sqrt{N/M}<\/annotation><\/semantics><\/math>,\nfalls\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M<\/mi><mo>≪<\/mo><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">M\\ll N<\/annotation><\/semantics><\/math>;\nzu viele Iterationen verringern die Erfolgswahrscheinlichkeit wieder.\nDiese Rotation gilt bei idealem Orakel und idealer Diffusion.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>r<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi mathvariant=\"normal\">arcsin<\/mi><msqrt><mfrac><mi>M<\/mi><mi>N<\/mi><\/mfrac><\/msqrt><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_r=\\sin^2\\!\\left((2r+1)\\arcsin\\sqrt{\\frac{M}{N}}\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=4<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">M=1<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">arcsin<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>π<\/mi><mi>/<\/mi><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\theta=\\arcsin(1/2)=\\pi/6<\/annotation><\/semantics><\/math>.\nVor einer Grover-Iteration gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_0=1/4<\/annotation><\/semantics><\/math>;\nnach einer Iteration\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_1=\\sin^2(\\pi/2)=1<\/annotation><\/semantics><\/math>.\nNach zwei Iterationen fällt die Wahrscheinlichkeit wieder auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>.\nDer Kurvenplot visualisiert diese ideale, periodische\nAmplitudenrotation.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_121_DE.svg\"\nalt=\"Grover-Erfolgswahrscheinlichkeit für vier Zustände mit einer markierten Lösung bei null bis drei Iterationen.\" />\n<figcaption aria-hidden=\"true\">Grover-Erfolgswahrscheinlichkeit für vier\nZustände mit einer markierten Lösung bei null bis drei\nIterationen.<\/figcaption>\n<\/figure>\n<p><em>Die Amplitudenverstärkung erreicht nach einer Iteration ihr\nMaximum.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">P_0<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>M<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mi>N<\/mi><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">M=1,N=4<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie viele vollständige Grover-Iterationen sind im Beispiel\nideal?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>O<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msqrt><mi>N<\/mi><\/msqrt><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">O(\\sqrt N)<\/annotation><\/semantics><\/math>\nnicht gleich der garantierten gesamten Laufzeit eines Geräts?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1/4<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Eine Iteration.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Orakelimplementierung, Zustandserzeugung, Gatterfehler und\nMesswiederholungen kosten zusätzlich Zeit.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der Ausdruck ist kein allgemeiner quadratischer\nGeschwindigkeitsgewinn für beliebige Probleme. Die Zahl M muss bekannt\noder abgeschätzt werden; reale Geräte benötigen Fehlerbudgets und\nendliche Präzision.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Algorithmische Vorteile sind ohne ein Modell für Störungen\nunvollständig. <a href=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://learning.quantum.ibm.com/course/fundamentals-of-quantum-algorithms/grovers-algorithm\">IBM Quantum Learning – Grover’s Algorithm<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Amplitudenverstärkung und Abfragekomplexität einer unstrukturierten Suche; Fachlicher Bezug zur Lektion: M34-L4 – Grover-Suche und Quanten-Amplitudenverstärkung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M34-L5 – Dichtematrizen, Dekohärenz und Quantenkanäle<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M34-L1: Bloch-Kugel; M34-L3: ideale\nGatter.<\/p>\n<p><strong>Lernziel:<\/strong> Für einen ausdrücklich definierten\nMischkanal den Ausgabestatus und die Messwahrscheinlichkeiten\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Reale Qubits wechselwirken mit Umgebung und Steuertechnik. Reine\nZustände allein reichen nicht aus, wenn das Experiment unbekannte\nZustände mischt oder Kohärenz verliert. Eine Dichtematrix ist positiv,\nhermitesch und besitzt Spur eins. Ein physikalischer Quantenkanal ist\nvollständig positiv und spurerhaltend (CPTP), damit auch verschränkte\nEingänge konsistent transformiert werden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Betrachte als didaktisches Beispiel\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℰ<\/mi><mi>p<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ρ<\/mi><mo>+<\/mo><mi>p<\/mi><mi>I<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal E_p(\\rho)=(1-p)\\rho+pI/2<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>≤<\/mo><mi>p<\/mi><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0\\le p\\le1<\/annotation><\/semantics><\/math>.\nDas ist eine Mischung aus unverändertem Eingang und maximal gemischtem\nQubit, nicht die einzig mögliche Parametrisierung eines\nPauli-Fehlerkanals. Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ρ<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\rho_0=|0\\rangle\\langle0|<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℰ<\/mi><mi>p<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>ρ<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">diag<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mi>p<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal E_p(\\rho_0)=\\operatorname{diag}(1-p/2,p/2)<\/annotation><\/semantics><\/math>.\nJeder Bloch-Vektor schrumpft um den Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1-p<\/annotation><\/semantics><\/math>;\nReinheit und Messkontrast nehmen ab.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"script\">ℰ<\/mi><mi>p<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ρ<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>ρ<\/mi><mo>+<\/mo><mfrac><mi>p<\/mi><mn>2<\/mn><\/mfrac><mi>I<\/mi><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mn>0<\/mn><mo>≤<\/mo><mi>p<\/mi><mo>≤<\/mo><mn>1<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathcal E_p(\\rho)=(1-p)\\rho+\\frac p2I,\\qquad 0\\le p\\le1.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Starte mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|0\\rangle<\/annotation><\/semantics><\/math>\nund wähle\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}2<\/annotation><\/semantics><\/math>.\nDann gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(0)=0{,}9<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P(1)=0{,}1<\/annotation><\/semantics><\/math>\nund die Bloch-Länge sinkt auf 0,8. Der Vektorpfeil in der Grafik zeigt\nidealen und abgeschwächten z-Anteil; die Messwahrscheinlichkeiten sind\nzusätzlich aufgetragen. Die Parameterwahl ist illustrativ, kein\ngemessener Geräteraum.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_068_DE.svg\"\nalt=\"Idealer Bloch-Vektor schrumpft nach einem Mischkanal auf 80 Prozent; P null und P eins sind angegeben.\" />\n<figcaption aria-hidden=\"true\">Idealer Bloch-Vektor schrumpft nach einem\nMischkanal auf 80 Prozent; P null und P eins sind\nangegeben.<\/figcaption>\n<\/figure>\n<p><em>Beispiel eines isotropen Mischkanals für ein\nEingangsqubit.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P(1)<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}4<\/annotation><\/semantics><\/math>\nund Eingang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|0\\rangle<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Bloch-Länge resultiert bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=1<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum genügt bloße Positivität ohne vollständige Positivität nicht\nfür beliebige verschränkte Eingänge?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>:\nDer Zustand ist maximal gemischt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Erweiterung des Kanals auf ein unberührtes Partnersystem muss\nebenfalls positive Zustände erzeugen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der Mischkanal repräsentiert nicht alle Dekohärenzprozesse.\nPhasendämpfung und Amplitudendämpfung verändern Zustände\nunterschiedlich; ein einziger Parameter charakterisiert keine\nvollständige Hardware.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Quantenkanäle machen Fehler modellierbar und motivieren\nFehlerkorrektur. <a href=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://quantum.cloud.ibm.com/learning/en/courses/general-formulation-of-quantum-information/quantum-channels/quantum-channel-basics\">IBM Quantum Learning – Quantum Channel Basics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Dichtematrizen und Quantenkanäle; gewählter Mischparameter ist ausdrücklich lektionsintern definiert; Fachlicher Bezug zur Lektion: M34-L5 – Dichtematrizen, Dekohärenz und Quantenkanäle · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M34-L6 – Quantenfehlerkorrektur mit dem Dreiqubit-Code<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M34-L3: CNOT; M34-L5:\nQuantenkanäle.<\/p>\n<p><strong>Lernziel:<\/strong> Die Syndromtabelle für einen einzelnen\nX-Fehler und die logische Fehlerwahrscheinlichkeit herleiten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein unbekanntes Qubit lässt sich nicht beliebig kopieren.\nQuantenfehlerkorrektur verteilt stattdessen Quanteninformation kohärent\nauf einen größeren Hilbertraum. Der Dreiqubit-Wiederholungscode bildet\nα|0⟩+β|1⟩ auf α|000⟩+β|111⟩ ab. Paritätsmessungen können dann anzeigen,\nwelches physikalische Qubit durch einen Bitflip X gestört wurde, ohne\ndie logischen Koeffizienten auszulesen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Die zwei Stabilisatoren\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>1<\/mn><\/msub><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_1Z_2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><msub><mi>Z<\/mi><mn>3<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_2Z_3<\/annotation><\/semantics><\/math>\nhaben im fehlerfreien Code den Messwert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>+<\/mi><mn>1<\/mn><mo>,<\/mo><mi>+<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(+1,+1)<\/annotation><\/semantics><\/math>.\nEin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mn>1<\/mn><\/msub><annotation encoding=\"application/x-tex\">X_1<\/annotation><\/semantics><\/math>-Fehler\nliefert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>+<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,+1)<\/annotation><\/semantics><\/math>,\nein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">X_2<\/annotation><\/semantics><\/math>-Fehler\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,-1)<\/annotation><\/semantics><\/math>\nund ein\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mn>3<\/mn><\/msub><annotation encoding=\"application/x-tex\">X_3<\/annotation><\/semantics><\/math>-Fehler\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>+<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(+1,-1)<\/annotation><\/semantics><\/math>.\nWird jedes physikalische Qubit unabhängig mit Wahrscheinlichkeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\ngeflippt, versagt die Mehrheitskorrektur bei zwei oder drei Flips.\nDaraus folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">l<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><msup><mi>p<\/mi><mn>3<\/mn><\/msup><mo>=<\/mo><mn>3<\/mn><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><msup><mi>p<\/mi><mn>3<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">P_{\\mathrm{fail}}=3p^2(1-p)+p^3=3p^2-2p^3<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">l<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>p<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><msup><mi>p<\/mi><mn>3<\/mn><\/msup><mo>=<\/mo><mn>3<\/mn><msup><mi>p<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><msup><mi>p<\/mi><mn>3<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{\\mathrm{fail}}=3p^2(1-p)+p^3=3p^2-2p^3.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}1<\/annotation><\/semantics><\/math>\nist die unkorrigierte Bitflip-Wahrscheinlichkeit 10 %, nach idealer\neinmaliger Kodierung und Korrektur beträgt sie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>028<\/mn><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>8<\/mn><mspace width=\"0.167em\"><\/mspace><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0{,}028=2{,}8\\,\\%<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt die vier Syndrome und ihre Zuordnung zu keinem Fehler,\nX1, X2 und X3. Zusätzliche Gatter- und Messfehler wurden in diesem\nZahlenbeispiel bewusst nicht berücksichtigt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_241_DE.svg\"\nalt=\"Vier Syndrompaare der Z-Paritätsmessung mit zugehörigem Einqubit-Bitflip oder keinem Fehler.\" />\n<figcaption aria-hidden=\"true\">Vier Syndrompaare der Z-Paritätsmessung\nmit zugehörigem Einqubit-Bitflip oder keinem Fehler.<\/figcaption>\n<\/figure>\n<p><em>Syndromzuordnung für den idealen Dreiqubit-Bitflip-Code.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welches Syndrom weist auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mn>2<\/mn><\/msub><annotation encoding=\"application/x-tex\">X_2<\/annotation><\/semantics><\/math>\nhin?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welcher logische Fehleranteil ergibt sich bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=0{,}2<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Korrigiert der Wiederholungscode allein allgemeine\nZ-Phasenfehler?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,-1)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mo>−<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>3<\/mn><\/msup><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>104<\/mn><\/mrow><annotation encoding=\"application/x-tex\">3(0{,}2)^2-2(0{,}2)^3=0{,}104<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein. Dafür benötigt man geeignete zusätzliche\nKodierung/Stabilisatoren.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Abschätzung verlangt unabhängige, ausschließlich bitumkehrende\nFehler und perfekte Fehlerdetektion. Korrelationen, Leckage,\nPhasenfehler und fehlerhafte Korrekturschaltungen können den Vorteil\naufheben.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Fehlertoleranz verbindet abstrakte Codes mit zuverlässiger Hardware.\n<a href=\"index.html?course=university_physics&amp;module=M34&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://learning.quantum.ibm.com/course/foundations-of-quantum-error-correction/correcting-quantum-errors\">IBM Quantum Learning – Correcting Quantum Errors<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Dreifacher Wiederholungscode und getrennte Bit-/Phasenfehler; Fachlicher Bezug zur Lektion: M34-L6 – Quantenfehlerkorrektur mit dem Dreiqubit-Code · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M34-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M34-L7 – Quantensensorik, Messpräzision und Quantennetzwerke<\/h1>\n<p><strong>Kursbereich:<\/strong> M34 – Master: Quanteninformation und Quantentechnologien<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M32: Messtechnik; M33: Atom- und\noptische Physik; M34-L2: Verschränkung.<\/p>\n<p><strong>Lernziel:<\/strong> Die 1/√N-Präzisionsskalierung ideal\nunabhängiger Sonden erklären und die Grenze zu vernetzten Protokollen\nziehen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Quantentechnologien nutzen präparierte Zustände für Messung und\nInformationsübertragung. Atomuhren und interferometrische Sensoren\nverwandeln eine unbekannte Phase in statistisch auswertbare Ereignisse.\nVerschränkung oder gequetschte Zustände können unter geeigneten Annahmen\ndie Präzision verbessern, aber Verlust, Totzeit und technische Drift\nverhindern universelle Garantien. Quantennetzwerke verteilen\nQuantenzustände oder Verschränkung und benötigen weiterhin klassische\nSteuer- und Kommunikationskanäle.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>N<\/mi><annotation encoding=\"application/x-tex\">N<\/annotation><\/semantics><\/math>\nideale unabhängige Einzelsonden bei optimaler Messlage und konstanter\nKontraststärke sinkt die typische Phasenunsicherheit wie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>ϕ<\/mi><mo>∝<\/mo><mn>1<\/mn><mi>/<\/mi><msqrt><mi>N<\/mi><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\phi\\propto1/\\sqrt N<\/annotation><\/semantics><\/math>.\nDies ist die Schrotrausch-Skalierung; der Vorfaktor hängt vom konkreten\nSensor ab. Korrelationen können bei idealer Ressourcenzählung unter\ngeeigneten Modellen eine\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/N<\/annotation><\/semantics><\/math>-Skalierung\nermöglichen, sind aber gegenüber Störungen empfindlich. Die\nPräzisionsskalierung ist keine Aussage zur Sicherheit von\nQuantenschlüsselverteilung.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>ϕ<\/mi><mrow><mi mathvariant=\"normal\">i<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">p<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">n<\/mi><mi mathvariant=\"normal\">t<\/mi><\/mrow><\/msub><mo>∝<\/mo><mfrac><mn>1<\/mn><msqrt><mi>N<\/mi><\/msqrt><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta\\phi_{\\mathrm{independent}}\\propto\\frac1{\\sqrt N}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Erhöhe die Zahl unabhängiger idealer Sonden von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=100<\/annotation><\/semantics><\/math>\nauf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>=<\/mo><mn>400<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N=400<\/annotation><\/semantics><\/math>.\nDann halbiert sich die Phasenunsicherheit: in einer normierten\nBeispielrechnung von 0,10 auf 0,05 rad. In der Grafik sind die\ntheoretischen Werte für verschiedene N dargestellt; es handelt sich\nnicht um eine reale Uhren- oder Sensorkennlinie. Ein Quantennetzwerk\nkann Messdaten koordinieren, verbessert aber die Skalierung nicht ohne\nweitere Ressourcen oder ein geeignetes Protokoll.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_232_DE.svg\"\nalt=\"Ideale Phasenunsicherheit sinkt mit steigender Sondenzahl wie eins durch Quadratwurzel N; Werte bei N 100 und 400 hervorgehoben.\" />\n<figcaption aria-hidden=\"true\">Ideale Phasenunsicherheit sinkt mit\nsteigender Sondenzahl wie eins durch Quadratwurzel N; Werte bei N 100\nund 400 hervorgehoben.<\/figcaption>\n<\/figure>\n<p><em>Normierte Schrotrausch-Skalierung für unabhängige ideale\nSonden.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welcher Faktor entsteht bei Vervierfachung von N für die ideale\nUnsicherheit?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie skaliert die idealisierte Varianz, falls die Standardabweichung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∝<\/mo><msup><mi>N<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\propto N^{-1/2}<\/annotation><\/semantics><\/math>\nist?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist eine quantenphysikalische Messgrenze keine\nSicherheitsgarantie für ein Netzwerk?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Die Unsicherheit halbiert sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1/N<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Sicherheit hängt von Protokollannahmen, Implementierung,\nAuthentisierung und Seitenkanälen ab.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Formel gilt für unabhängige, ideal beobachtete Sonden und\nbeschreibt nicht jeden Sensor. Technisches Rauschen erzeugt oft eine\nSättigung. Quantennetze brauchen verlustarme Komponenten und\nProtokollvalidierung; die Fachquellen ersetzen keine\nSicherheitsprüfung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>M34 verbindet die Physik einzelner Qubits mit Korrelationen,\nSchaltungen, Algorithmen, Rauschen, Fehlerkorrektur und praktischen\nAnwendungen.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/quantum-information-science/quantum-sensing-explained\">NIST – Quantum Sensing Explained<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Quantensensoren, Atomuhren und praktische Messanwendungen; nicht alle Grenzformeln belegt; Fachlicher Bezug zur Lektion: M34-L7 – Quantensensorik, Messpräzision und Quantennetzwerke · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/publications/optimal-quantum-measurements-expectation-values-observables\">NIST – Optimal Quantum Measurements of Expectation Values of Observables<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Ideale 1/√N- bzw. 1/N-Skalierungen unter verschiedenen Messannahmen; Fachlicher Bezug zur Lektion: M34-L7 – Quantensensorik, Messpräzision und Quantennetzwerke · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/quantum-communications-and-networks\">NIST – Quantum Communications and Networks<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Entwicklung und Charakterisierung von Quantennetzwerken; keine pauschale Sicherheitsgarantie; Fachlicher Bezug zur Lektion: M34-L7 – Quantensensorik, Messpräzision und Quantennetzwerke · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
